mapper.update:
MERGE INTO TB_RECENT_ITEM T
USING DUAL ON (
    T.ENP_ID    = #{empId}
    AND T.ITEM_TYPE = #{itemType}
    AND T.ITEM_ID   = #{itemId}
)
WHEN MATCHED THEN
    UPDATE SET ACCESSED_DT = SYSDATE
WHEN NOT MATCHED THEN
    INSERT (RECENT_ITEM_ID, EMP_ID, ITEM_TYPE, ITEM_ID, ACCESSED_DT)
    VALUES (SEQ_RECENT_ITEM.NEXTVAL, #{empId}, #{itemType}, #{itemId}, SYSDATE)
